head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05401";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05401.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_58", fn: function(){ return ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "c_when_62", fn: function(){ return ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLSX'); } }, { id: "c_when_66", fn: function(){ return ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOCX'); } }, { id: "c_when_70", fn: function(){ return ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPTX'); } }, { id: "c_when_74", fn: function(){ return ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_78", fn: function(){ return (!(((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP') || ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLSX') || ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOCX') || ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT' || (dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPTX') || ((dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'))); } }, { id: "btn_Modify", fn: function(){ return ((dma_notiDetail.get("listDtlConfrm") ?? (() => { throw new Error("unresolved:" + "notiDetail.listDtlConfrm"); })())   ===  '미확인'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_55", entity: "dlt_notiDetailListNotifyDataAttachVO", countIds: [], cells: [{ childId: "__rc6", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }, { childId: "__rc10", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }, { childId: "__rc11", fn: function (v, i) { return " " + String(v("listDtlAttachAileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldfil05401: 진입 키 listnotify 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_ksdConfrmReservTpCd1_onclick
 * @description rd_ksdConfrmReservTpCd1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_ksdConfrmReservTpCd1_onclick = function(e){
    try {
        scwin.checkKsdConfrmReservTpCd(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05401.rd_ksdConfrmReservTpCd1_onclick' }); }
};

/**
 * @method
 * @name btn_listNotiFileDown_onclick
 * @description btn_listNotiFileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_listNotiFileDown_onclick = async function(e){
    try {
        await scwin.listNotiFileDown('' + dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "listDtlNotiId") + '','' + dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "seq") + '','' + dlt_notiDetailListNotifyDataAttachVO.getCellData(0, "listDtlAttachAileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05401.btn_listNotiFileDown_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05401.btn_Search_onclick' }); }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function(e){
    try {
        await scwin.modify('' + dma_notiDetail.get("listDtlNotiId") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05401.btn_Modify_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/list/listNotify.do",
        ref: "dma_ModifyReq",
        target: "dlt_notiDetailListNotifyDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/list/listNotify.do",
        ref: "dma_SearchReq",
        target: "dlt_notiDetailListNotifyDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_listNotiFileDown
 * @description list Noti File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_listNotiFileDown = async function () {
    try { return await $c.data.downFile("/common/irDataFileDown.do", "", ($c.util.getComponent("dma_listNotiFileDownReq") ? $c.util.getComponent("dma_listNotiFileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name setRadioValue
 * @description set Radio Value 처리
 * @param {*} radioName radioName
 * @param {*} formParamName formParamName
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRadioValue = async function (radioName, formParamName, msg) {
    const i = 0;
    const form = (document.irDataForm || { elements: [] });
    {
        const rv = String($c.util.getComponent('dma_ModifyReq').get(radioName) ?? '');
        if (rv === '') {
            await $c.win.alert(msg + " 항목을 선택해주세요.");
            return false;
        }
        $c.util.getComponent('dma_ModifyReq').set(formParamName, rv);
    }
    return true;
};

/**
 * @method
 * @name checkKsdConfrmReservTpCd
 * @description check Ksd Confrm Reserv Tp Cd 처리
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.checkKsdConfrmReservTpCd = function (gubun) {
    if (gubun === '1') {
        $c.util.getComponent('ipt_ksdReservRsn').setValue('');
        $c.util.getComponent('ipt_ksdReservRsn').readOnly = true;
    } else {
        if (gubun === '2') {
            $c.util.getComponent('ipt_ksdReservRsn').readOnly = false;
            $c.util.getComponent("ipt_ksdReservRsn").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        }
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} listDtlNotiId listDtlNotiId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (listDtlNotiId) {
    if (!await scwin.setRadioValue("ksdConfrmReservTpCd1", "ksdConfrmReservTpCd", "예탁원확인")) {
        $c.util.getComponent('rd_ksdConfrmReservTpCd1').focus();
        return;
    }
    if ($c.util.getComponent("dma_ModifyReq").get("ksdConfrmReservTpCd") === '2' && ($c.util.getComponent('ipt_ksdReservRsn').getValue() == null ? '' : String($c.util.getComponent('ipt_ksdReservRsn').getValue())) === '') {
        await $c.win.alert('유보사유를 입력하세요.');
        $c.util.getComponent("ipt_ksdReservRsn").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return;
    }
    const rtn = await $c.win.confirm('저장 하시겠습니까?');
    if (rtn === 1) {
        (document.irDataForm || { elements: [] }).action = '/list/listNotify.do';
        $c.util.getComponent('dma_ModifyReq').set('listDtlNotiId', listDtlNotiId);
        $c.util.getComponent('dma_ModifyReq').set('method', 'modifyListNotify');
        const nr = await scwin.tx_fn_Modify();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil05400/jldfil05400.xml", { "listDtlNotiId": listDtlNotiId, "method": 'modifyListNotify' });
        }
        document.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil05400/jldfil05400.xml');
    }
};

/**
 * @method
 * @name listNotiFileDown
 * @description list Noti File Down 처리
 * @param {String} listDtlNotiId listDtlNotiId
 * @param {*} seq seq
 * @param {String} listDtlAttachAileNm listDtlAttachAileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listNotiFileDown = async function (listDtlNotiId, seq, listDtlAttachAileNm) {
    $c.util.getComponent('dma_ModifyReq').set('listDtlNotiId', listDtlNotiId);
    $c.util.getComponent('dma_ModifyReq').set('seq', seq);
    $c.util.getComponent('dma_ModifyReq').set('listDtlAttachAileNm', listDtlAttachAileNm);
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    await scwin.tx_fn_listNotiFileDown();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    (document.irDataForm || { elements: [] }).action = '/list/listNotify.do';
    $c.util.getComponent('dma_ModifyReq').set('method', 'listListNotify');
    const nr = await scwin.tx_fn_Search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil05400/jldfil05400.xml", { "method": 'listListNotify' });
    }
};
